// Symbols are drawn on a 960 unit grid whose origin is the bottom left, hence the group shifted down.
private fun symbol(name: String, path: String): ImageVector = ImageVector.Builder(
    name = name,
    defaultWidth = 24.dp,
    defaultHeight = 24.dp,
    viewportWidth = 960f,
    viewportHeight = 960f,
).addGroup(translationY = 960f)
    .addPath(pathData = PathParser().parsePathString(path).toNodes(), fill = SolidColor(Color.Black))
    .clearGroup()
    .build()
